package mcpserver

// smartFormTools are the console's Smart Form tools on one public method each: the component
// catalog, folders, release history, file history, the trash and a page run like the runtime.
var smartFormTools = []parityTool{
	{Name: "smart_form_components", Method: "cdu/catalog/get", BriefUnlessNarrowed: true, Description: "The CDU component catalog a Smart Form page config is validated against. Without types or kind it lists every type with its kind, category and label (brief); then call it with types for the ones you need: their props (the JSON Schema the validator applies), events, state and api. Use ONLY these types and props: sim-api refuses an unknown type or prop when the page is saved, naming the closest ones. A field caption is the label prop of TextInput or Select; DatePicker has none, so put a Label before it."},
	{Name: "smart_form_folders_create", Method: "app_folder/create", Description: "Create folders in a Smart Form's develop tree, all or none (actorId is the appId). A new page is a folder pages/<page> (folderId: the id of pages from smart_form_files_get) holding a config file, which smart_form_files_create then adds. Titles are not unique: reuse a folder that exists."},
	{Name: "smart_form_releases_list", Method: "release/list", Description: "List a Smart Form's releases, newest first (actorId is the appId): id, releaseNumber, envId, status (active, archived, rolled_back), title; envId narrows to one environment (productionEnvId of smart_form_files_get). An env keeps snapshots for its newest 5 releases only."},
	{Name: "smart_form_release_diff", Method: "release/diff", Description: "Compare two releases of a Smart Form (actorId is the appId): what vs (B) has that releaseId (A) has not (added), the reverse (removed) and files whose content differs (modified), by names and hashes only. To preview a rollback pass the active release as releaseId and the one to restore as vs."},
	{Name: "smart_form_release_rollback", Method: "release/rollback", Destructive: true, Description: "Roll an environment back to an earlier release (releaseId; its env is the one rolled back; actorId is the appId). It replaces the env's whole content with that release's snapshot as a new active release (history is kept, so a rollback is undone by rolling back again); on production the short URL moves to it. Name the release and what changes (smart_form_release_diff) and get the user's yes first."},
	{Name: "smart_form_file_versions_list", Method: "file_version/list", Description: "List the version history of one Smart Form file, newest first (actorId is the appId, fileId from smart_form_files_get; a file in the trash too): each version's id, operation (create, update, rename, move, delete, restore, rollback), userId, time and source. An update, rename or move version holds the file as it was BEFORE that change. A file keeps its newest 50."},
	{Name: "smart_form_file_version_get", Method: "file_version/get", Description: "Read one version of a Smart Form file with its source (actorId is the appId; versionId from smart_form_file_versions_list)."},
	{Name: "smart_form_file_rollback", Method: "file/rollback", Destructive: true, Description: "Put a develop file back into the state a version holds: title, type, folder and source (actorId is the appId). Rolling back to the newest update undoes the latest edit; a file in the trash is restored. It first records the current state as a version, so it can be undone, and is checked like a save. Production files are read-only: use smart_form_release_rollback. Confirm with the user first."},
	{Name: "smart_form_trash_list", Method: "trash/list", Description: "List the deleted folders and files of a Smart Form environment (actorId is the appId, envId: developEnvId of smart_form_files_get) with their ids and objType."},
	{Name: "smart_form_trash_restore", Method: "trash/restore", Destructive: true, Description: "Restore folders and files of a Smart Form from the trash, all or none, with their ids, into the folders they were deleted from (actorId is the appId; items {id, objType folder|file} from smart_form_trash_list). A folder comes back alone: restore what was deleted with it as items of their own. Confirm with the user first."},
	{Name: "smart_form_page_render", Method: "page/render", Description: "Render a Smart Form page as the runtime does, to check it works: ref and envTitle (develop to test before release, production) and page (empty: the start page), or target. Returns the page tree, bindings, viewModel and locale, or the error that breaks it. It runs the page's initialization process, if it has one."},
	{Name: "smart_form_page_submit", Method: "page/submit", Description: "Submit a Smart Form page's form as the runtime does (formId is the Form node's id in the page, formData its values), addressed like smart_form_page_render. It runs the page's submit process (Corezoid /send) and whatever that writes: use it to test a form the user asked you to test, never to send real data on their behalf without a yes."},
}
